index 0000000..e5086c6
--- /dev/null
+++ b/src/test/TestCollisionMesh.cpp
@@ -0,0 +1,209 @@
+// Copyright © 2008-2026 Pioneer Developers. See AUTHORS.txt for details
+// Licensed under the terms of the GPL v3. See licenses/GPL-3.txt
+
+// Regression tests for https://github.com/pioneerspacesim/pioneer/issues/6110
+//
+// A Skipjack docked at a ground station (Cydonia, a "new_ground" starport)
+// takes hull damage and stalls the instant it lifts off its pad, as if it
+// struck something. These tests replay that liftoff headlessly (dummy
+// renderer, same pattern as src/modelcompiler.cpp: no GL context, no display)
+// with the engine's own code wherever it can run without a game:
+//
+//  - models come from the engine's model cache (Pi::FindModel), the ship as a
+//    per-body instance the way ModelBody::SetModel takes it;
+//  - the station's docking bays come from the engine's own SpaceStationType
+//    built from data/stations/new_ground.json (GetStageTransform for the
+//    DOCKED stage is what SpaceStation::GetBayTransform uses);
+//  - the ship is seated on a bay with SpaceStation::PositionDockedShip's rule
+//    (bay transform lowered by the ship's landing offset, which Ship::Init
+//    reads from the model's "tag_landing" marker);
+//  - ship and station collision geometry are then collided with
+//    Geom::Collide, at rest and while climbing straight up off the pad.
+//
+// Any contact reported there is a contact the running game turns into the
+// hull damage and climb stall shown in the bug report.
+
+#include "CollMesh.h"
+#include "FileSystem.h"
+#include "ModManager.h"
+#include "ModelCache.h"
+#include "Pi.h"
+#include "SpaceStationType.h"
+#include "collider/CollisionContact.h"
+#include "collider/Geom.h"
+#include "doctest.h"
+#include "graphics/Graphics.h"
+#include "graphics/dummy/RendererDummy.h"
+#include "matrix4x4.h"
+#include "scenegraph/CollisionGeometry.h"
+#include "scenegraph/Model.h"
+#include "scenegraph/Tag.h"
+#include "versioningInfo.h"
+
+#include <memory>
+#include <vector>
+
+namespace {
+	void InitHeadlessEngine()
+	{
+		// Just enough of the engine to load models: a filesystem rooted at the
+		// repository's data/ directory, a dummy renderer that performs no real
+		// GL calls (as modelcompiler.cpp's SetupRenderer() does), and the
+		// model cache Pi::FindModel serves models from.
+		static bool s_initialised = false;
+		if (s_initialised) return;
+		s_initialised = true;
+
+		// Using Pi (for its model cache) links in the GUI application code,
+		// which needs OutputVersioningInfo() from libpioneer-lib; calling it
+		// here (it only logs library versions) keeps it in the unittest link.
+		OutputVersioningInfo();
+
+		FileSystem::Init();
+		FileSystem::userFiles.MakeDirectory("");
+		ModManager::Init();
+
+		Graphics::RendererDummy::RegisterRenderer();
+
+		Graphics::Settings videoSettings = {};
+		videoSettings.rendererType = Graphics::RENDERER_DUMMY;
+		videoSettings.width = 800;
+		videoSettings.height = 600;
+		videoSettings.fullscreen = false;
+		videoSettings.hidden = true;
+		videoSettings.vsync = false;
+		videoSettings.useTextureCompression = false;
+		videoSettings.useAnisotropicFiltering = false;
+		videoSettings.iconFile = "";
+		videoSettings.title = "unittest";
+
+		Graphics::Renderer *renderer = Graphics::Init(videoSettings);
+		REQUIRE(renderer != nullptr);
+		if (!Pi::modelCache)
+			Pi::modelCache = new ModelCache(renderer);
+	}
+
+	// A per-body instance of a model, as ModelBody::SetModel creates it.
+	std::unique_ptr<SceneGraph::Model> ModelInstance(const char *modelName)
+	{
+		InitHeadlessEngine();
+		SceneGraph::Model *model = Pi::FindModel(modelName, false);
+		REQUIRE(model != nullptr);
+		return std::unique_ptr<SceneGraph::Model>(model->MakeInstance());
+	}
+
+	// The engine's surface station type used by Cydonia.
+	const SpaceStationType &CydoniaStationType()
+	{
+		InitHeadlessEngine();
+		static std::unique_ptr<SpaceStationType> s_type(new SpaceStationType("new_ground", "stations/new_ground.json"));
+		REQUIRE(s_type->IsSurfaceStation());
+		return *s_type;
+	}
+
+	// Ship::Init's landing offset: the local Y of the model's "tag_landing"
+	// marker, or zero when the model has none.
+	double LandingOffset(const SceneGraph::Model *ship)
+	{
+		const SceneGraph::Tag *tag = ship->FindTagByName("tag_landing");
+		return tag ? tag->GetGlobalTransform().GetTranslate().y : 0.0;
+	}
+
+	// Ship transform in station space when it is docked on `bay`, `lift`
+	// metres above its docked position along the pad's up axis
+	// (SpaceStation::PositionDockedShip with the station at the origin and
+	// the ship centred on the pad).
+	matrix4x4d ShipOnBay(const SpaceStationType &type, int bay, double landingOffset, double lift)
+	{
+		matrix4x4d padTrans = matrix4x4d(type.GetStageTransform(bay, DockStage::DOCKED));
+		padTrans.Translate(0.0, -landingOffset, 0.0);
+		return padTrans * matrix4x4d::Translation(0.0, lift, 0.0);
+	}
+
+	struct LiftoffScene {
+		const SpaceStationType &type = CydoniaStationType();
+		std::unique_ptr<SceneGraph::Model> ship = ModelInstance("skipjack");
+		std::unique_ptr<SceneGraph::Model> station = ModelInstance("new_ground");
+		double landingOffset = LandingOffset(ship.get());
+
+		int NumBays() const { return int(type.NumDockingPorts()); }
+
+		std::vector<CollisionContact> Collide(int bay, double lift) const
+		{
+			RefCountedPtr<CollMesh> shipMesh = ship->GetCollisionMesh();
+			RefCountedPtr<CollMesh> stationMesh = station->GetCollisionMesh();
+			REQUIRE(shipMesh);
+			REQUIRE(stationMesh);
+			REQUIRE(shipMesh->GetGeomTree() != nullptr);
+			REQUIRE(stationMesh->GetGeomTree() != nullptr);
+
+			const matrix4x4d shipTrans = ShipOnBay(type, bay, landingOffset, lift);
+			Geom shipGeom(shipMesh->GetGeomTree(), shipTrans, shipTrans.GetTranslate(), ship.get());
+			Geom stationGeom(stationMesh->GetGeomTree(), matrix4x4d::Identity(), vector3d(0.0), station.get());
+			return shipGeom.Collide(&stationGeom);
+		}
+	};
+} // namespace
+
+TEST_CASE("Skipjack resting on a Cydonia landing pad does not touch the pad")
+{
+	LiftoffScene scene;
+	REQUIRE(scene.NumBays() == 6);
+	for (int bay = 0; bay < scene.NumBays(); bay++) {
+		const std::vector<CollisionContact> contacts = scene.Collide(bay, 0.0);
+		INFO("bay ", bay + 1, ": ", contacts.size(), " contact(s) at rest");
+		CHECK(contacts.empty());
+	}
+}
+
+TEST_CASE("Skipjack climbing off a Cydonia landing pad never touches the pad")
+{
+	LiftoffScene scene;
+	REQUIRE(scene.NumBays() == 6);
+	for (int bay = 0; bay < scene.NumBays(); bay++) {
+		int firstHitCm = -1;
+		// climb straight up from 2 cm to 10 m above the docked position
+		for (int cm = 2; cm <= 1000; cm += 2) {
+			if (!scene.Collide(bay, cm * 0.01).empty()) {
+				firstHitCm = cm;
+				break;
+			}
+		}
+		INFO("bay ", bay + 1, ": first contact ", firstHitCm, " cm above the docked position (-1 = none)");
+		CHECK(firstHitCm == -1);
+	}
+}
+
+TEST_CASE("Skipjack collision mesh keeps its shape outside the lowest point")
+{
+	// Neighbouring regression guard: a clean liftoff must not come from
+	// gutting the hull's collision geometry (collapsing or deleting large
+	// parts of the mesh, or rescaling the whole ship). These bounds are well
+	// inside the base commit's own measurements (top of hull at local Y ~2.9,
+	// overall radius ~22.3, ~100 collision triangles).
+	std::unique_ptr<SceneGraph::Model> model = ModelInstance("skipjack");
+	RefCountedPtr<CollMesh> collMesh = model->GetCollisionMesh();
+	REQUIRE(collMesh);
+	const Aabb &aabb = collMesh->GetAabb();
+	CHECK(aabb.max.y > 2.0);
+	CHECK(aabb.GetRadius() > 15.0);
+	CHECK(collMesh->GetGeomTreeNumTris() > 50);
+}
+
+TEST_CASE("Cydonia landing pads still catch a Skipjack that sinks into them")
+{
+	// Neighbouring regression guard: a clean liftoff must not come from the
+	// pads (or the ship's underside) losing their collision geometry. A
+	// Skipjack pushed a metre below its docked position must still register a
+	// contact with the pad's docking surface on every pad.
+	LiftoffScene scene;
+	REQUIRE(scene.NumBays() == 6);
+	for (int bay = 0; bay < scene.NumBays(); bay++) {
+		const std::vector<CollisionContact> contacts = scene.Collide(bay, -1.0);
+		bool touchesDockingSurface = false;
+		for (const CollisionContact &c : contacts)
+			touchesDockingSurface |= (c.geomFlag & SceneGraph::CollisionGeometry::DOCKING) != 0;
+		INFO("bay ", bay + 1, ": ", contacts.size(), " contact(s) one metre below the docked position");
+		CHECK(touchesDockingSurface);
+	}
+}
#!/usr/bin/env python3
"""Turn the JUnit report into the task reward.

The reward is binary: 1.0 only when every configured f2p and p2p test is found exactly once in the
report and passed; otherwise 0.0. f2p_passed / f2p_total and p2p_passed / p2p_total record how close
a run came. A `--rubric fail` verdict zeroes the reward; absent or ungraded never lowers it
(rubric_passed = -1). The verifier reads test outcomes only, never the candidate's source.
"""
import html
import json
import os
import sys
import xml.etree.ElementTree as ET

# Canonical reward writer + --rubric gate. Proven against a real harbor run, and verified
# against all five outcome cases (perfect run, failed rubric, ungraded rubric, partial f2p,
# p2p regression).
#
# verifier.py carries TASK-SPECIFIC logic, so this is a PROPOSAL to merge by hand.
#
# CRITICAL - reward.json MUST be a FLAT map of numbers, and exactly these seven keys:
#     {reward, tests_passed, f2p_passed, f2p_total, p2p_passed, p2p_total, rubric_passed}
# harbor parses it as VerifierResult.rewards: dict[str, float | int] and takes it in
# PREFERENCE to reward.txt. A nested dict, list, string or None raises a pydantic
# ValidationError that aborts the trial BEFORE any reward is recorded - while reward.txt
# still gets written inside the container, so the run looks scored when harbor in fact
# stored nothing.
#   rubric_passed: 1 pass / 0 fail / -1 not graded (no rubric shipped, or judge unavailable).
#
# THE POLICY IS BINARY. tests_passed is 1.0 only when every f2p passes AND every p2p still
# passes; a strict subset of f2p passing is 0.0, NOT 0.5. Partial credit would let a half-fix
# read as "solved" to pass@k, and nothing is lost by collapsing it because the four count keys
# carry the detail. An earlier version of this template documented reward.txt as a float in
# {0.0, 0.5, 1.0} with a failed rubric capping at 0.5; both were wrong.
#
# Registered with atexit so it writes LAST and overrides whatever a pre-existing local reward
# block already wrote - which is what makes this a safe patch onto a task being repaired
# rather than a rewrite of its scoring.

import atexit, json as _cj, os as _co, sys as _cs

_CANON_JSON = "/logs/verifier/reward.json"
_CANON_TXT = "/logs/verifier/reward.txt"
_canon = {}


def canon_reward(f2p_passed, f2p_total, p2p_passed, p2p_total, rubric):
    """THE reward policy for the whole corpus. BINARY -- there is no partial credit.

    tests_passed is 1.0 only when every f2p test passes AND every p2p test still passes. A
    strict subset of f2p passing is not partial progress worth scoring: the task is unsolved,
    so it is 0.0.

    reward is the same value, zeroed when the rubric judge failed a criterion. A "pass" or a
    "not graded" verdict never lowers the score -- the judge must never be able to penalise a
    run it could not grade.
    """
    f, t = int(f2p_passed), int(f2p_total)
    p, q = int(p2p_passed), int(p2p_total)
    solved = bool(t) and f == t and p == q
    tests_passed = 1.0 if solved else 0.0
    _canon.clear()
    _canon.update({
        "reward": 0.0 if rubric == "fail" else tests_passed,
        "tests_passed": tests_passed,
        "f2p_passed": f, "f2p_total": t,
        "p2p_passed": p, "p2p_total": q,
        "rubric_passed": {"pass": 1, "fail": 0}.get(rubric, -1),
    })
    return _canon["reward"]


@atexit.register
def _canon_flush():
    if not _canon:
        return
    try:
        _co.makedirs(_co.path.dirname(_CANON_JSON), exist_ok=True)
        with open(_CANON_JSON, "w") as _h:
            _cj.dump(_canon, _h, indent=2)
        # reward.txt too: harbor prefers reward.json, but the sandbox teardown script and the
        # lighthouse UI read reward.txt. Writing both from one dict means they cannot disagree.
        with open(_CANON_TXT, "w") as _h:
            _h.write(str(_canon["reward"]))
    except Exception as _exc:
        print("WARNING: could not write %s: %s" % (_CANON_JSON, _exc), file=_cs.stderr)


def rubric_verdict(argv):
    """The verdict test.sh hands in as `--rubric pass|fail|""`.

    Anything that is not an explicit pass/fail -- including the empty string test.sh passes
    when judge.py wrote no verdict -- means "not graded", which must never penalise the run.
    """
    if "--rubric" not in argv:
        return None
    i = argv.index("--rubric")
    value = argv[i + 1].strip().lower() if i + 1 < len(argv) else ""
    return value if value in ("pass", "fail") else None


# --- call site, once, wherever the reward is decided -----------------------------
#     canon_reward(len(f2p_pass), len(F2P),
#                  len(P2P) - len(p2p_fail), len(P2P),
#                  rubric_verdict(sys.argv[1:]))
#
# Per-test detail, if wanted, rides along as extra `f2p::<name>` / `p2p::<name>` = 1.0/0.0
# SCALAR keys added to the same flat dict -- never as a nested map.


CONF = json.load(open("/tests/config.json"))
F2P, P2P = CONF["f2p"], CONF["p2p"]
REPORT = os.environ.get("JUNIT_OUT", "/logs/verifier/junit.xml")
OUT_DIR = "/logs/verifier"


def load_junit(path):
    """Every reported test, keyed by "classname name" and by name; a key seen twice with different
    outcomes counts as failed."""
    results = {}
    if not os.path.exists(path):
        return results
    try:
        root = ET.parse(path).getroot()
    except ET.ParseError:
        return results
    for tc in root.iter("testcase"):
        tags = {c.tag for c in tc}
        outcome = "skip" if "skipped" in tags else ("fail" if tags & {"failure", "error"} else "pass")
        full = f"{tc.get('classname', '')} {tc.get('name', '')}".strip()
        for key in {full, tc.get("name", "")}:
            if key in results and results[key] != outcome:
                results[key] = "fail"
            else:
                results[key] = outcome
    return results


def junit_key(test_id):
    """A pytest node id (tests/test_x.py::TestA::test_b[png]) as the JUnit report names it
    ("tests.test_x.TestA test_b[png]"); other ids unchanged."""
    if "::" not in test_id:
        return test_id
    parts = test_id.split("::")
    mod = parts[0][:-3] if parts[0].endswith(".py") else parts[0]
    return f"{'.'.join([mod.replace('/', '.')] + parts[1:-1])} {parts[-1]}"


def resolve(test_id, results):
    """The outcome of one configured test: an exact key match first (the id as written, or a
    pytest node id in JUnit form), else the single reported test whose key ends with it. Missing
    or ambiguous counts as not passed."""
    keys = [test_id, junit_key(test_id)]
    if " :: " in test_id:  # "file :: describe › test" (playwright list output)
        keys.append(test_id.replace(" :: ", " ", 1))
    if " > " in test_id:  # "describe > test": jest-junit joins with a space, playwright with " › "
        head, rest = test_id.split(" > ", 1)
        keys += [test_id.replace(" > ", " "), test_id.replace(" > ", " › "), head + " " + rest.replace(" > ", " › ")]
    keys += [k.replace('"', "") for k in keys]  # jest-junit drops quotation marks from names
    keys += [html.unescape(k) for k in keys]  # an id copied from a JUnit file may keep &apos; &quot;
    keys = list(dict.fromkeys(keys))
    for key in keys:
        if key in results:
            return results[key]
    for key in keys:
        hits = {k: v for k, v in results.items() if k.endswith(key)}
        if hits and len(set(hits.values())) == 1:
            return next(iter(hits.values()))
        if hits:
            return "ambiguous"
    # "file > test" with a describe level left out: a test in that file whose name ends the same
    parts = test_id.split(" > ")
    if len(parts) >= 2 and ("." in parts[0] or "/" in parts[0]):
        hits = {k: v for k, v in results.items() if k.startswith(parts[0] + " ") and k.endswith(parts[-1])}
        if hits and len(set(hits.values())) == 1:
            return next(iter(hits.values()))
        if hits:
            return "ambiguous"
    return "missing"


def main():
    results = load_junit(REPORT)
    detail = {}
    f2p_ok = 0
    for t in F2P:
        r = resolve(t, results)
        detail[f"f2p::{t}"] = r
        f2p_ok += r == "pass"
    p2p_ok = 0
    for t in P2P:
        r = resolve(t, results)
        detail[f"p2p::{t}"] = r
        p2p_ok += r == "pass"
    reward_value = canon_reward(f2p_ok, len(F2P), p2p_ok, len(P2P), rubric_verdict(sys.argv[1:]))
    os.makedirs(OUT_DIR, exist_ok=True)
    json.dump(detail, open(f"{OUT_DIR}/reward_detail.json", "w"), indent=2)
    print(json.dumps(dict(_canon)))


if __name__ == "__main__":
    main()

